async function commit(change: Change) {
  const reach = reachOf(change)                // known from the change alone
  await order(reach)                           // wait only on changes it meets
  const residing = residence(change)           // each holon to its store
  const problems = judge(residing)               // every problem at once
  if (problems.length) return { refused: problems }
  const { act, ids } = mint(residing)            // which handle became which id
  const reply = await offer(write(act))        // a line per store, to each head
  if (reply === "moved") return commit(change) // again, over what was taken in
  return { act, ids }
}
